function bestDiscount(order, rules) {
  const best = rules.map((rule) => rule(order)).reduce((max, kobo) => Math.max(max, kobo), 0);
  return Math.min(best, order.subtotalKobo);
}

const rules = [
  (o) => (o.subtotalKobo >= 5000000 ? 250000 : 0),
  (o) => (o.firstOrder ? 100000 : 0),
  (o) => 9999999,
];
console.log(bestDiscount({ subtotalKobo: 6000000, firstOrder: true }, rules.slice(0, 2)));
console.log(bestDiscount({ subtotalKobo: 50000, firstOrder: false }, rules));
console.log(bestDiscount({ subtotalKobo: 50000 }, []));

