const partial = (fn, ...preset) => (...rest) => fn(...preset, ...rest);

function shippingKobo(zones, city, kg) {
  const zone = zones[city] ?? zones.default;
  return zone.base + Math.ceil(kg) * zone.perKg;
}
const ZONES = { Lagos: { base: 100000, perKg: 20000 }, default: { base: 250000, perKg: 50000 } };

const ship = partial(shippingKobo, ZONES);
console.log(ship("Lagos", 1.5), ship("Kano", 1));
